-- 调整清洗规则备注、描述
UPDATE "ATT_CLEAN_RULE"
SET "DESCRIPTION" = '通过正则表达式匹配符合特定规则的文本，并将其批量替换为指定内容',
    "EXAMPLE" = '使用 (\d{4})/(\d{2})/(\d{2}) 匹配 2026/08/18，替换为 $1-$2-$3 后得到 2026-08-18',
    "USE_CASE" = '批量统一文本中的日期格式，提高数据处理效率'
WHERE "ID" = 11;